import pandas as pd
import numpy as np

def generate_synthetic_time_series(n_samples=100, start_time=0, end_time=100, noise_level=0.1, random_state=None):
    if random_state is not None:
        np.random.seed(random_state)

    # Generate a time series with a sudden decrease towards the end
    time = np.arange(start_time, end_time, 1)
    value = np.concatenate([np.linspace(start_time, end_time - 10, n_samples - 10), np.linspace(end_time, start_time, 10)])
    value += np.random.normal(scale=noise_level, size=n_samples)

    return pd.DataFrame({'time': time, 'value': value})

import pandas as pd
import random

def generate_synthetic_time_series(n_samples=100, start_time=0, end_time=100, min_value=0, max_value=100):
    time_series = []
    for i in range(n_samples):
        time = start_time + i
        value = min_value + (max_value - min_value) * random.random()
        if i > 0.9 * n_samples:
            if i % 2 == 0:
                value -= 10
        time_series.append((time, value))

    return pd.DataFrame(time_series, columns=['time', 'value'])

