from sklearn.cluster import KMeans
import pandas as pd

def detect_temporalbehavior(sensor_data, window_size=10, threshold=0.1, num_clusters=2):
    if len(sensor_data) < window_size:
        return False

    end_data = sensor_data.tail(int(len(sensor_data)*threshold))
    if len(end_data) < window_size:
        return False

    X = end_data['value'].rolling(window=window_size, center=True).mean().values.reshape(-1, 1)
    kmeans = KMeans(n_clusters=num_clusters)
    kmeans.fit(X)

    if kmeans.cluster_centers_[1] > kmeans.cluster_centers_[0] * threshold:
        return True
    else:
        return False

from statistics import mean, stdev
import pandas as pd

def detect_temporalbehavior(sensor_data, window_size=None, percentage=0.1):
    if window_size is None:
        window_size = int(len(sensor_data) * percentage)

    if window_size < 2:
        raise ValueError("Window size must be greater than or equal to 2.")

    sensor_data = sensor_data.sort_values('time')
    baseline_mean = mean(sensor_data['value'][:-window_size])
    baseline_std = stdev(sensor_data['value'][:-window_size])

    if baseline_std == 0:
        return False

    recent_values = sensor_data['value'][-window_size:]
    recent_mean = mean(recent_values)

    if recent_mean > baseline_mean + 3 * baseline_std:
        return True
    else:
        return False

