from statistics import mean, stdev

def generate_synthetic_time_series(num_points=100, start_time=0, end_time=100, mean_value=0, std_dev_value=1):
    time_series = []
    for i in range(num_points):
        time_series.append({'time': start_time + i, 'value': mean_value + random.gauss(0, std_dev_value)})

    # Add a sudden increase at the end of the time series
    for i in range(int(num_points * 0.1), num_points):
        time_series.append({'time': start_time + i, 'value': mean_value + 4 * std_dev_value})

    return pd.DataFrame(time_series)

