from sklearn.cluster import KMeans
import pandas as pd

def detect_temporalbehavior(sensor_data, window_size=10, threshold=0.1, n_clusters=2):
    if not isinstance(sensor_data, pd.DataFrame):
        raise ValueError("sensor_data must be a pandas DataFrame")

    if not 0 < threshold < 1:
        raise ValueError("threshold must be between 0 and 1")

    end_index = int(len(sensor_data) * threshold)
    window_data = sensor_data.iloc[-window_size:]
    if end_index < window_size:
        return False

    kmeans = KMeans(n_clusters=n_clusters)
    kmeans.fit(window_data[['value']])
    last_cluster = kmeans.predict(sensor_data.iloc[end_index-window_size:end_index][['value']])

    if last_cluster.sum() == 0:
        return False

    last_value = sensor_data.iloc[end_index]['value']
    if last_value > kmeans.cluster_centers_[1]['value']:
        return True
    return False

