import pandas as pd
import random

def generate_synthetic_time_series(seed=None, num_samples=100, start_time=0, end_time=100, noise_std=1):
    if seed is not None:
        random.seed(seed)

    times = [start_time + i for i in range(num_samples)]
    values = [i for i in range(num_samples)]

    # Add some noise to the time series
    values = [x + random.gauss(0, noise_std) for x in values]

    # Add a sudden drop at the end
    for i in range(num_samples-10, num_samples):
        values[i] -= 5 * noise_std

    return pd.DataFrame({"time": times, "value": values})

