from sklearn.cluster import KMeans
import pandas as pd

def detect_temporalbehavior(sensor_data, window=10, threshold=0.1, cluster_number=2):
    if len(sensor_data) < window:
        return False

    end_data = sensor_data.tail(int(len(sensor_data)*threshold))
    if len(end_data) < window:
        return False

    kmeans = KMeans(n_clusters=cluster_number)
    kmeans.fit(end_data['value'].to_numpy().reshape(-1, 1))

    if kmeans.cluster_centers_[0] > kmeans.cluster_centers_[1] * threshold:
        return True
    else:
        return False

import pandas as pd
import numpy as np

def detect_temporalbehavior(sensor_data, window_size=10, percentage=0.1):
    if not isinstance(sensor_data, pd.DataFrame):
        raise ValueError("sensor_data must be a pandas DataFrame")

    if len(sensor_data) < window_size:
