import pandas as pd
import numpy as np

def generate_synthetic_time_series(data_size=100, start_time=0, end_time=100, spike_time=None, spike_value=None):
    if spike_time is None:
        spike_time = end_time - int(data_size * 0.1)
    if spike_value is None:
        spike_value = np.mean(np.random.normal(size=data_size)) + np.std(np.random.normal(size=data_size)) * 3

    time_series = pd.DataFrame({'time': np.arange(start_time, end_time), 'value': np.random.normal(size=data_size)})
    time_series.loc[spike_time, 'value'] = spike_value
    return time_series

