import pandas as pd
from statsmodels.tsa.stattools import adfuller
def detect_temporalbehavior(sensor_data, threshold=10, alpha=0.05):
    # Calculate the size of the last 10% of the time series data
    last_data_size = int(len(sensor_data) * threshold / 100)
    # Calculate the mean and standard deviation of the last 10% of the time series data
    last_data_mean = sensor_data.iloc[-last_data_size:]['value'].mean()
    last_data_std = sensor_data.iloc[-last_data_size:]['value'].std()
    # Check for stationarity of the last 10% of the time series data
    adf_result = adfuller(sensor_data.iloc[-last_data_size:]['value'].dropna())
    if adf_result[1] > alpha:
        # If the last 10% of the time series data is not stationary, check if the mean is greater than the threshold
        if last_data_mean > threshold:
            return True
        else:
            return False
    else:
        # If the last 10% of the time series data is stationary, check if the mean is greater than the threshold and if the mean + std is greater than the threshold
        if last_data_mean > threshold and last_data_mean + last_data_std > threshold:
            return True
        else:
            return False

