import numpy as np
import pandas as pd
import random

def generate_synthetic_time_series(n_samples=100, noise_level=0.1, increase_level=0.5, increase_prob=0.5):
    # Generate a time series with a sudden increase
    data = np.concatenate([np.arange(n_samples//2), np.arange(n_samples//2, n_samples) * increase_level + np.random.normal(scale=noise_level, size=n_samples-n_samples//2)])
    if random.random() < increase_prob:
        data[-n_samples//10:] = data[-n_samples//10:] * (1 + increase_level) + np.random.normal(scale=noise_level, size=n_samples//10)
    return pd.Series(data)

