import pandas as pd
import numpy as np
from statsmodels.tsa.stattools import adfuller

def generate_synthetic_time_series(n_samples=100, start_time=0, end_time=100, noise_level=0.1, seed=None):
    if seed is not None:
        np.random.seed(seed)
    time = np.linspace(start_time, end_time, n_samples)
    value = np.zeros(n_samples)
    last_10percent = int(n_samples*0.1)
    value[-last_10percent:] = np.random.normal(loc=1.5, scale=noise_level, size=last_10percent)
    return pd.DataFrame({'time': time, 'value': value})

def detect_temporalbehavior(sensor_data, threshold=1.0, alpha=0.05):
    sensor_data = sensor_data.sort_values('time')
    last_10percent = int(len(sensor_data)*0.1)
    last_data = sensor_data.iloc[-last_10percent:]
    result = adfuller(last_data['value'])
    if result[1] > threshold:
        return True
    else:
        return False

