import random
import pandas as pd

def generate_synthetic_time_series(start_time=pd.Timestamp("2022-01-01"), end_time=pd.Timestamp("2022-01-10"), freq='1min', mean_value=50, std_dev=10, spike_chance=0.1, spike_multiplier=2):
    time_index = pd.date_range(start_time, end_time, freq=freq)
    value_series = pd.Series(index=time_index, data=[mean_value + random.gauss(0, std_dev) for t in time_index])
    for i in range(len(time_index)-1):
        if random.random() < spike_chance:
            value_series[time_index[i]] *= spike_multiplier
    return value_series.to_frame('value')

