from sklearn.ensemble import IsolationForest
import pandas as pd

def detect_temporalbehavior(sensor_data, window_size=10, threshold=0, verbose=False):
    sensor_data = sensor_data.sort_values('time')
    last_10perc = sensor_data.iloc[-int(len(sensor_data)*0.1):]
    if last_10perc.shape[0] < 2*window_size:
        return False

    X = last_10perc['value'].values.reshape(-1, 1)
    if verbose:
        print("Instantiating Isolation Forest")
    clf = IsolationForest(random_state=0, contamination=threshold)
    if verbose:
        print("Fitting model")
    clf.fit(X)
    if verbose:
        print("Predicting anomaly score")
    scores = clf.decision_function(X)
    if verbose:
        print("Detecting sudden increase")
    return scores.mean() > 0

