import pandas as pd
import numpy as np
import random

def generate_synthetic_time_series(num_points=100, start_time=pd.Timestamp("2022-01-01 00:00:00"), end_time=pd.Timestamp("2022-01-01 01:00:00"), noise_level=0.1):
    time_values = pd.date_range(start=start_time, end=end_time, periods=num_points)
    value_values = np.zeros(num_points)
    for i in range(int(0.9 * num_points), num_points):
        value_values[i] = value_values[i-1] + random.uniform(-noise_level, noise_level)
        if i % 10 == 0:
            value_values[i] += random.uniform(0.5, 1.5) * noise_level
    return pd.DataFrame({"time": time_values, "value": value_values})

