from sklearn.cluster import KMeans
import pandas as pd
import numpy as np

def detect_temporalbehavior(sensor_data, window_size=10, threshold=0.1, cluster_count=2):
    if len(sensor_data) < window_size:
        return False

    end_data = sensor_data.tail(int(len(sensor_data)*threshold))
    if len(end_data) < window_size:
        return False

    X = end_data.values
    X = X[::-1] # reverse the data to consider the recent data first
    kmeans = KMeans(n_clusters=cluster_count, random_state=0).fit(X.reshape(-1, 1))

    if kmeans.cluster_centers_[1] - kmeans.cluster_centers_[0] > threshold:
        return True
    else:
        return False

