import pandas as pd

def detect_temporalbehavior(sensor_data, window_size=10, threshold=0, verbose=False):
    sensor_data = sensor_data.sort_values('time')
    end_data = sensor_data.tail(int(len(sensor_data)*0.1))
    if len(end_data) < window_size:
        return False

    X = end_data['value'].values.reshape(-1, 1)
    if verbose:
        print("Fitting Isolation Forest")
    clf = IsolationForest(random_state=0).fit(X)
    if verbose:
        print("Predicting anomalies")
    y_pred = clf.predict(X)
    if verbose:
        print("Calculating percentage of anomalies")
    percentage_anomalies = sum(y_pred == -1) / len(y_pred)

    if percentage_anomalies > threshold:
        return True
    else:
        return False

from sklearn.ensemble import IsolationForest
import pandas as pd

def detect_temporalbehavior(sensor_data, threshold=100, window_size=0.1, persist=False):
    if not isinstance(sensor_data, pd.DataFrame):
        raise ValueError("sensor_data must be a pandas DataFrame")

    if persist:
        data_last_10perc = sensor_data.iloc[-int(len(sensor_data)*window_size):]
    else:
        data_last_10perc = sensor_data.tail(int(len(sensor_data)*window_size))

    if len(data_last_10perc) < 2:
        return False

    clf = IsolationForest(n_estimators=100, contamination_probability=threshold/100)
    clf.fit(data_last_10perc[['value']])
    anomaly_score = clf.decision_function(data_last_10perc[['value']])

    if persist:
        data_last_10perc['anomaly_score'] = anomaly_score

    return anomaly_score.mean() > threshold

