import numpy as np
import pandas as pd
import random

def generate_synthetic_time_series(n_samples=100, start_time=0, end_time=100, noise_level=0.1):
    time = np.arange(start_time, end_time, (end_time - start_time)/n_samples)
    value = np.zeros(n_samples)
    for i in range(int(n_samples*0.9), n_samples):
        value[i] = np.random.normal(1, noise_level, 1)[0]
    return pd.DataFrame({'time': time, 'value': value})

import pandas as pd
import numpy as np
from statsmodels.tsa.stattools import adfuller

def generate_synthetic_time_series(data_size=100, start_value=100, end_value=50, trend='up'):
    # Generate a time index
    time_index = pd.date_range(start='2022-01-01', periods=data_size, freq='D')

    # Generate a synthetic time series
    if trend == 'up':
        time_series = pd.Series(np.linspace(start_value, end_value, data_size), index=time_index)
    elif trend == 'down':
        time_series = pd.Series(np.linspace(end_value, start_value, data_size), index=time_index)
    else:
        time_series = pd.Series(np.random.normal(loc=start_value, scale=10, size=data_size), index=time_index)

    # Add a 'value' column
    time_series = time_series.rename('value')

    # Perform the Augmented Dickey-Fuller Test
    adf_result = adfuller(time_series['value'])

    # If the null hypothesis is rejected, then the time series is stationary
    if adf_result[1] < 0.05:
        return time_series
    else:
        return generate_synthetic_time_series(data_size=data_size, start_value=start_value, end_value=end_value, trend=trend)
